answers.sql:
SELECT full_name, pay
FROM staff
WHERE pay BETWEEN 20000 AND 45000;

SELECT b.full_name, o.title
FROM staff b
LEFT JOIN outlet o ON b.outlet_no = o.outlet_no;

SELECT b.full_name, m.full_name AS Boss_Name
FROM staff b
LEFT JOIN staff m ON b.reports_to = m.staff_no;

SELECT pay_mode, COUNT(*) AS Bill_Count
FROM bill
GROUP BY pay_mode;

SELECT a.title
FROM outlet a
WHERE NOT EXISTS (SELECT 1 FROM bill b WHERE b.outlet_no = a.outlet_no);

SELECT d.dish_name
FROM dish d
WHERE NOT EXISTS (SELECT 1 FROM bill_item bi WHERE bi.dish_code = d.dish_code);

SELECT bill_no, bill_date
FROM bill
WHERE YEAR(bill_date) = 2024 AND tip = 0;

SELECT b.full_name
FROM staff b
WHERE b.pay > (SELECT AVG(x.pay) FROM staff x);

SELECT title
FROM outlet
WHERE monthly_rent = (SELECT MAX(monthly_rent) FROM outlet);

UPDATE staff
SET pay = pay * 1.12
WHERE duty = 'Waiter';

UPDATE dish
SET price = price - 10
WHERE course = 'Drink';

UPDATE bill
SET tip = 0
WHERE tip IS NULL;
